          <path fill="#FBBF24" d="M96 480c-17.7 0-32-14.3-32-32s14.3-32 32-32l256 0c17.7 0 32 14.3 32 32s-14.3 32-32 32L96 480zM384 384c0 8.8-7.2 16-16 16L80 400c-8.8 0-16-7.2-16-16c0-40.2 24.3-75.7 61.8-90.7l23.5-9.4C137.9 264.4 128 238.6 128 208c0-30.7 13.9-46.7 34.2-60.6c2.8-1.9 5.8-3.7 8.9-5.4C172.9 123 176 100.8 176 80c0-14.1 6.5-27.4 17.6-36.1s25.8-11.8 39.5-8.4c38.7 9.7 68.3 39.3 78 78c3.4 13.7 .3 28.4-8.4 39.5s-22 17.6-36.1 17.6c-4.6 0-9.2-.6-13.6-1.9c-2.3 8.3-6.4 16.5-12.2 24.3c15.1 7.2 31.8 12.5 49.3 15.6c14.2 2.5 24.9 14.8 24.9 29.2c0 8.3-3.4 16.1-9.4 21.9l-22.6 21.7c38.4 17.8 63.4 56.4 63.4 99.6zM224 96a16 16 0 1 0 0-32 16 16 0 1 0 0 32z" />
